const question = $('Set Debate Config').item.json.question;
const propOpen = $('Agent A — Proposer').item.json.output;
const oppOpen = $('Agent B — Opposer').item.json.output;
const propReb = $('Agent A Rebuttal').item.json.output;
const oppReb = $('Agent B Rebuttal').item.json.output;
const verdict = $('Judge Agent').item.json.output;

const formatted = `## Debate: ${question}

### 🟢 PROPOSER (Opening)
${propOpen}

### 🔴 OPPOSER (Opening)
${oppOpen}

### 🟢 PROPOSER (Rebuttal)
${propReb}

### 🔴 OPPOSER (Rebuttal)
${oppReb}

### ⚖️ JUDGE VERDICT
${verdict}`;

return [{ json: { debate: formatted, question, verdict } }];
